/**
 * Drizzle table definitions used for type-safe queries.
 *
 * The SQL in ./migrations.ts is the source of truth for DDL (constraints,
 * partial indexes, the generated `search` tsvector column). Keep the two in
 * sync when adding columns. `resources.search` is intentionally not mapped:
 * it is generated by Postgres and only referenced through raw SQL.
 */
import {
  bigserial,
  boolean,
  date,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";

const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
};

export const users = pgTable("users", {
  id: uuid("id").primaryKey().defaultRandom(),
  email: text("email").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
  firstName: text("first_name").notNull(),
  surname: text("surname").notNull(),
  role: text("role", { enum: ["learner", "teacher", "admin"] }).notNull(),
  dateOfBirth: date("date_of_birth"),
  gradeLevel: text("grade_level"),
  guardianEmail: text("guardian_email"),
  ecNumber: text("ec_number").unique(),
  schoolName: text("school_name"),
  teacherStatus: text("teacher_status", { enum: ["pending", "verified", "rejected"] }),
  status: text("status", { enum: ["active", "suspended"] }).notNull().default("active"),
  lastLoginAt: timestamp("last_login_at", { withTimezone: true }),
  ...timestamps,
});

export const sessions = pgTable("sessions", {
  /** SHA-256 of the session token; the raw token only ever lives in the cookie. */
  id: text("id").primaryKey(),
  userId: uuid("user_id")
    .notNull()
    .references(() => users.id, { onDelete: "cascade" }),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  userAgent: text("user_agent"),
});

export const resources = pgTable("resources", {
  id: uuid("id").primaryKey().defaultRandom(),
  slug: text("slug").notNull().unique(),
  title: text("title").notNull(),
  description: text("description").notNull().default(""),
  tier: text("tier").notNull(),
  level: text("level"),
  subject: text("subject"),
  resourceType: text("resource_type").notNull(),
  audience: text("audience", { enum: ["public", "educator"] }).notNull().default("public"),
  year: smallint("year"),
  examSession: text("exam_session", { enum: ["june", "november"] }),
  paperNumber: smallint("paper_number"),
  fileKey: text("file_key").notNull(),
  previewKey: text("preview_key"),
  coverKey: text("cover_key"),
  fileSizeBytes: integer("file_size_bytes").notNull(),
  pageCount: integer("page_count").notNull(),
  checksumSha256: text("checksum_sha256").notNull().unique(),
  downloadCount: integer("download_count").notNull().default(0),
  isPublished: boolean("is_published").notNull().default(true),
  createdBy: uuid("created_by").references(() => users.id, { onDelete: "set null" }),
  ...timestamps,
});

export const resourceEvents = pgTable("resource_events", {
  id: bigserial("id", { mode: "number" }).primaryKey(),
  resourceId: uuid("resource_id")
    .notNull()
    .references(() => resources.id, { onDelete: "cascade" }),
  userId: uuid("user_id").references(() => users.id, { onDelete: "set null" }),
  kind: text("kind", { enum: ["view", "download"] }).notNull(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

/** One row per (resource, user, Harare day) — makes the public counter spam-resistant. */
export const resourceDailyUniques = pgTable(
  "resource_daily_uniques",
  {
    resourceId: uuid("resource_id")
      .notNull()
      .references(() => resources.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    day: date("day").notNull(),
  },
  (t) => [primaryKey({ columns: [t.resourceId, t.userId, t.day] })],
);

/** One row per (guest, Harare day, resource) — enforces the anonymous daily download allowance. */
export const guestDownloads = pgTable(
  "guest_downloads",
  {
    guestId: text("guest_id").notNull(),
    day: date("day").notNull(),
    resourceId: uuid("resource_id")
      .notNull()
      .references(() => resources.id, { onDelete: "cascade" }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.guestId, t.day, t.resourceId] })],
);

export const supportTickets = pgTable("support_tickets", {
  id: uuid("id").primaryKey().defaultRandom(),
  reference: text("reference").notNull().unique(),
  firstName: text("first_name").notNull(),
  surname: text("surname").notNull(),
  email: text("email").notNull(),
  phone: text("phone"),
  category: text("category").notNull(),
  message: text("message").notNull(),
  userId: uuid("user_id").references(() => users.id, { onDelete: "set null" }),
  status: text("status", { enum: ["open", "resolved"] }).notNull().default("open"),
  deliveryStatus: text("delivery_status", { enum: ["pending", "sent", "failed", "not_configured"] })
    .notNull()
    .default("pending"),
  deliveryError: text("delivery_error"),
  ipHash: text("ip_hash"),
  ...timestamps,
});

export const errorLogs = pgTable("error_logs", {
  id: bigserial("id", { mode: "number" }).primaryKey(),
  source: text("source", { enum: ["server", "client"] }).notNull(),
  level: text("level", { enum: ["error", "warning"] }).notNull().default("error"),
  message: text("message").notNull(),
  stack: text("stack"),
  url: text("url"),
  fingerprint: text("fingerprint").notNull(),
  context: jsonb("context").$type<Record<string, unknown>>().notNull().default({}),
  userId: uuid("user_id").references(() => users.id, { onDelete: "set null" }),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

export type UserRow = typeof users.$inferSelect;
export type ResourceRow = typeof resources.$inferSelect;
export type SupportTicketRow = typeof supportTickets.$inferSelect;
export type ErrorLogRow = typeof errorLogs.$inferSelect;
